PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT ?gn WHERE {
  SELECT ?gn (SUM(?amt) AS ?total) WHERE {
    SELECT DISTINCT ?c ?amt ?gn WHERE {
      ?c a :Contract ; :supplier ?s ; :amount ?amt ; :sector ?sec .
      ?sec :within ?x . ?x :code "5415" .
      ?s :group ?g . ?g :name ?gn .
    }
  } GROUP BY ?gn ORDER BY DESC(?total) LIMIT 5
}
